from collections import defaultdict
from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        total = sum(nums)
        # alternating sum is bounded by [-total, total]
        if k > total or k < -total:
            return -1

        CAP = limit + 1  # sentinel for "product exceeds limit"

        # dp[(sum, parity_of_next_index)] -> set of achievable products (capped)
        dp = defaultdict(set)

        for i, x in enumerate(nums):
            rem = 12 * (n - 1 - i)  # max absolute change achievable with remaining elements after this one

            # prune states that can never reach k even using element i and beyond
            rem_incl = 12 * (n - i)
            dead = [key for key in dp if abs(key[0] - k) > rem_incl]
            for key in dead:
                del dp[key]

            new_items = []
            for (s, par), prods in list(dp.items()):
                if par == 0:
                    ns = s + x
                else:
                    ns = s - x
                # after adding x, remaining elements can change sum by at most rem
                if abs(ns - k) > rem:
                    continue
                np = par ^ 1
                for p in prods:
                    q = p * x
                    if q > limit:
                        q = CAP
                    new_items.append((ns, np, q))

            # start a new subsequence with x at index 0 (even position)
            if abs(x - k) <= rem:
                q = x if x <= limit else CAP
                new_items.append((x, 1, q))

            for ns, np, q in new_items:
                dp[(ns, np)].add(q)

        best = -1
        for (s, par), prods in dp.items():
            if s == k:
                for p in prods:
                    if p <= limit and p > best:
                        best = p
        return best

