    DIRS=[(2,-2,0),(2,0,-2),(-2,2,0),(0,2,-2),(-2,0,2),(0,-2,2),(4,-2,-2),(-2,4,-2),(-2,-2,4),(-4,2,2),(2,-4,2),(2,2,-4)]
