from collections import defaultdict
from typing import List

class DualHeap:
    __slots__ = ('small', 'large', 'delayed', 'smallSize', 'largeSize', 'smallSum', 'largeSum')

    def __init__(self):
        self.small = []  # max-heap (negated) - lower half
        self.large = []  # min-heap - upper half
        self.delayed = defaultdict(int)
        self.smallSize = 0
        self.largeSize = 0
        self.smallSum = 0
        self.largeSum = 0

    def _prune(self, heap):
        if heap is self.small:
            while heap:
                num = -heap[0]
                if self.delayed[num]:
                    self.delayed[num] -= 1
                    heapq.heappop(heap)
                else:
                    break
        else:
            while heap:
                num = heap[0]
                if self.delayed[num]:
                    self.delayed[num] -= 1
                    heapq.heappop(heap)
                else:
                    break

    def _balance(self):
        if self.smallSize > self.largeSize + 1:
            self._prune(self.small)
            num = -heapq.heappop(self.small)
            self.smallSize -= 1
            self.smallSum -= num
            heapq.heappush(self.large, num)
            self.largeSize += 1
            self.largeSum += num
            self._prune(self.small)
        elif self.smallSize < self.largeSize:
            self._prune(self.large)
            num = heapq.heappop(self.large)
            self.largeSize -= 1
            self.largeSum -= num
            heapq.heappush(self.small, -num)
            self.smallSize += 1
            self.smallSum += num
            self._prune(self.large)

    def insert(self, num):
        if not self.small or num <= -self.small[0]:
            heapq.heappush(self.small, -num)
            self.smallSize += 1
            self.smallSum += num
        else:
            heapq.heappush(self.large, num)
            self.largeSize += 1
            self.largeSum += num
        self._balance()

    def erase(self, num):
        self.delayed[num] += 1
        if num <= -self.small[0]:
            self.smallSize -= 1
            self.smallSum -= num
            if num == -self.small[0]:
                self._prune(self.small)
        else:
            self.largeSize -= 1
            self.largeSum -= num
            if self.large and num == self.large[0]:
                self._prune(self.large)
        self._balance()

    def cost(self):
        self._prune(self.small)
        m = -self.small[0]
        return (m * self.smallSize - self.smallSum) + (self.largeSum - m * self.largeSize)


class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        # cost[s] = min operations to equalize window starting at s (length x)
        num_windows = n - x + 1
        cost = [0] * num_windows
        dh = DualHeap()
        for i in range(n):
            dh.insert(nums[i])
            if i >= x:
                dh.erase(nums[i - x])
            if i >= x - 1:
                cost[i - x + 1] = dh.cost()

        INF = float('inf')
        # dp: f[i] = min cost using j windows within first i elements
        prev = [0] * (n + 1)
        for j in range(1, k + 1):
            cur = [INF] * (n + 1)
            for i in range(x, n + 1):
                best = cur[i - 1]
                cand_prev = prev[i - x]
                if cand_prev < INF:
                    cand = cand_prev + cost[i - x]
                    if cand < best:
                        best = cand
                cur[i] = best
            prev = cur

        return prev[n]

