class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def f(N):
            if N <= 0:
                return 0
            digits = list(map(int, str(N)))
            L = len(digits)

            # Count numbers in [1, N] with no zero digit
            nz = 0
            for k in range(1, L):
                nz += 9 ** k
            ok = True
            for i in range(L):
                hi = digits[i] - 1
                if hi >= 1:
                    nz += hi * (9 ** (L - 1 - i))
                if digits[i] == 0:
                    ok = False
                    break
            if ok:
                nz += 1
            # Numbers with at least one zero digit: product = 0, always beautiful
            A = N - nz

            # B: numbers with all nonzero digits where product % sum == 0
            # free[j]: dict (sum, prod) -> count after j free digits (each 1-9)
            free = [None] * L
            free[0] = {(0, 1): 1}
            for j in range(1, L):
                cur = {}
                for (s, p), c in free[j - 1].items():
                    for d in range(1, 10):
                        key = (s + d, p * d)
                        if key in cur:
                            cur[key] += c
                        else:
                            cur[key] = c
                free[j] = cur

            B = 0
            # lengths m < L: fully free
            for m in range(1, L):
                for (s, p), c in free[m].items():
                    if p % s == 0:
                        B += c

            # length L: tight DP
            s0, p0 = 0, 1
            broke = False
            for i in range(L):
                rem = L - 1 - i
                for d in range(1, digits[i]):
                    s1 = s0 + d
                    p1 = p0 * d
                    for (s, p), c in free[rem].items():
                        if (p1 * p) % (s1 + s) == 0:
                            B += c
                if digits[i] == 0:
                    broke = True
                    break
                s0 += digits[i]
                p0 *= digits[i]
            if not broke:
                if p0 % s0 == 0:
                    B += 1

            return A + B

        return f(r) - f(l - 1)

