def main():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx+=1; M = int(data[idx]); idx+=1; K = int(data[idx]); idx+=1
    edges = []
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        u = int(data[idx]); idx+=1; v = int(data[idx]); idx+=1
        edges.append((u,v)); adj[u].append(v)
    # BFS unweighted distance
    dist = [-1]*(N+1); dist[1]=0
    q = deque([1])
    while q:
        x = q.popleft()
        for y in adj[x]:
            if dist[y]==-1:
                dist[y]=dist[x]+1; q.append(y)
    L = dist[N]
    INF = 10**9

    def mincut(D):
        # nodes: 0=S,1=T, node(v,i)=2+(v-1)*D+(i-1) for i in 1..D
        n = 2 + N*D
        graph = [[] for _ in range(n)]
        def add(a,b,c):
            graph[a].append([b,c,len(graph[b])])
            graph[b].append([a,0,len(graph[a])-1])
        def node(v,i): return 2+(v-1)*D+(i-1)
        # monotone chains
        for v in range(1,N+1):
            for i in range(2,D+1):
                add(node(v,i), node(v,i-1), INF)
        # force y_{N,i}=1
        add(0, node(N,D), INF)
        # force y_{1,i}=0
        add(node(1,1), 1, INF)
        for (u,v) in edges:
            # hard: y_{v,i}=1 => y_{u,i-1}=1
            for i in range(2,D+1):
                add(node(v,i), node(u,i-1), INF)
            # penalty
            for i in range(1,D+1):
                add(node(v,i), node(u,i), 1)
        # Dinic
        flow = 0
        while True:
            level = [-1]*n; level[0]=0
            dq = deque([0])
            while dq:
                x = dq.popleft()
                for e in graph[x]:
                    if e[1]>0 and level[e[0]]==-1:
                        level[e[0]] = level[x]+1
                        dq.append(e[0])
            if level[1]==-1:
                break
            it = [0]*n
            def dfs(x, f):
                if x==1: return f
                while it[x] < len(graph[x]):
                    e = graph[x][it[x]]
                    if e[1]>0 and level[e[0]]==level[x]+1:
                        d = dfs(e[0], min(f, e[1]))
                        if d>0:
                            e[1]-=d
                            graph[e[0]][e[2]][1]+=d
                            return d
                    it[x]+=1
                return 0
            while True:
                f = dfs(0, INF)
                if f==0: break
                flow += f
                if flow > K:
                    return flow
        return flow

    sys.setrecursionlimit(100000)
    upper = min(K, L)
    for D in range(upper, 0, -1):
        if mincut(D) <= K:
            print(D)
