        # Z-array of str2
        z = [0] * m
        z[0] = m
        l = r = 0
        for k in range(1, m):
            if k < r:
                z[k] = min(r - k, z[k - l])
            while k + z[k] < m and str2[z[k]] == str2[k + z[k]]:
                z[k] += 1
            if k + z[k] > r:
                l, r = k, k + z[k]

        Ts = [i for i, c in enumerate(str1) if c == 'T']

        # consistency check between consecutive T's (suffices by transitivity)
        for a, b in zip(Ts, Ts[1:]):
            p = b - a
            if p < m and z[p] < m - p:
                return ""

        word = ['a'] * L
        free = bytearray([1]) * L

        end = 0
        for t in Ts:
            s = max(t, end)
            if s < t + m:
                word[s:t + m] = s2[s - t:]
                free[s:t + m] = bytes(t + m - s)  # zeros -> not free
            end = t + m

        # DSU: rf[x] points toward greatest free index <= x
        rf = [i if free[i] else i - 1 for i in range(L)]

        def find(x):
            r0 = x
            while r0 >= 0 and rf[r0] != r0:
                r0 = rf[r0]
            while x >= 0 and rf[x] != x and x != r0:
                nxt = rf[x]
                rf[x] = r0
                x = nxt
            return r0

        Fs = [i for i in range(n) if str1[i] == 'F']

        # fix pass; repeat until stable (normally 1 fixing pass + 1 verify pass)
        while True:
            changed = False
            for i in Fs:
                if word[i:i + m] == s2:
                    j = find(i + m - 1)
                    if j < i:
                        return ""
                    # window equals str2, j is free so word[j]=='a' and str2[j-i]=='a'
                    word[j] = 'b'
                    rf[j] = j - 1
                    changed = True
            if not changed:
                break

        return ''.join(word)

