class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [factorial(i) for i in range(n + 1)]

        def completions(o, e, last_parity):
            # o odds and e evens remain; last placed element has parity last_parity (1=odd, 0=even)
            # number of valid alternating arrangements of the remaining elements
            if o + e == 0:
                return 1
            m = o + e
            if last_parity == 1:
                # remaining sequence starts with even: evens needed = ceil(m/2)
                need_e = (m + 1) // 2
                if e != need_e:
                    return 0
            else:
                need_o = (m + 1) // 2
                if o != need_o:
                    return 0
            return fact[o] * fact[e]

        avail = set(range(1, n + 1))
        odd_count = (n + 1) // 2
        even_count = n // 2
        result = []

        for pos in range(n):
            found = False
            for x in sorted(avail):
                xp = x % 2
                if pos > 0 and xp == result[-1] % 2:
                    continue
                o = odd_count - (1 if xp == 1 else 0)
                e = even_count - (1 if xp == 0 else 0)
                c = completions(o, e, xp)
                if c >= k:
                    result.append(x)
                    avail.remove(x)
                    if xp == 1:
                        odd_count -= 1
                    else:
                        even_count -= 1
                    found = True
                    break
                else:
                    k -= c
            if not found:
                return []
        return result

