class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        s = side
        pos = []
        for x, y in points:
            if y == 0:
                p = x
            elif x == s:
                p = s + y
            elif y == s:
                p = 2 * s + (s - x)
            else:  # x == 0
                p = 3 * s + (s - y)
            pos.append(p)
        pos.sort()
        total = 4 * s
        P = pos + [p + total for p in pos]
        N2 = 2 * n
        steps = k - 1

        def feasible(d):
            # nxt[j] = smallest index jj with P[jj] >= P[j] + d, else N2 (sentinel)
            nxt = [N2] * (N2 + 1)
            jj = 0
            for j in range(N2):
                if jj < j:
                    jj = j
                while jj < N2 and P[jj] - P[j] < d:
                    jj += 1
                nxt[j] = jj
            nxt[N2] = N2  # absorbing sentinel
            r = list(range(n))
            cur = nxt
            st = steps
            while st:
                if st & 1:
                    r = [cur[x] for x in r]
                st >>= 1
                if st:
                    cur = [cur[x] for x in cur]
            for i in range(n):
                x = r[i]
                if x < N2 and P[x] <= pos[i] + total - d:
                    return True
            return False

        lo, hi = 1, (4 * s) // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

