class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        p1, p2, p3 = p[:i1], p[i1+1:i2], p[i2+1:]
        l1, l2, l3 = len(p1), len(p2), len(p3)

        def occurrences(pat):
            m = len(pat)
            if m == 0:
                return list(range(n + 1))
            if m > n:
                return []
            # KMP failure function
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[i] != pat[k]:
                    k = fail[k - 1]
                if pat[i] == pat[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i in range(n):
                c = s[i]
                while k > 0 and c != pat[k]:
                    k = fail[k - 1]
                if c == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k - 1]
            return res

        A = occurrences(p1)  # starts of p1
        B = occurrences(p2)  # starts of p2
        C = occurrences(p3)  # starts of p3

        if not A or not B or not C:
            return -1

        ans = float('inf')
        # two pointers over sorted B
        ia = 0  # pointer into A: largest a with a + l1 <= b
        ic = 0  # pointer into C: smallest c with c >= b + l2
        lenA = len(A)
        lenC = len(C)
        best_a = -1
        for b in B:
            # advance ia while A[ia] + l1 <= b
            while ia < lenA and A[ia] + l1 <= b:
                best_a = A[ia]
                ia += 1
            if best_a < 0:
                continue
            target = b + l2
            while ic < lenC and C[ic] < target:
                ic += 1
            if ic >= lenC:
                break
            length = C[ic] + l3 - best_a
            if length < ans:
                ans = length

        return -1 if ans == float('inf') else ans

