class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(T: int) -> bool:
            # T = 0 always feasible
            if T == 0:
                return True
            cost = 0
            rem = 0  # visits already credited to current cell from previous bounces
            for i in range(n):
                need = (T + points[i] - 1) // points[i] - rem
                if need <= 0:
                    if i == n - 1:
                        return cost <= m
                    # must still pass through this cell
                    cost += 1
                    rem = 0
                else:
                    # step onto cell (1 move), then need-1 bounces (2 moves each)
                    cost += 2 * need - 1
                    rem = need - 1
                if cost > m:
                    return False
            return cost <= m

        lo, hi = 0, ((m + 1) // 2 + 1) * max(points)
        # binary search for largest feasible T
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

