def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1]); A = int(data[2]); B = int(data[3])
    ivs = []
    idx = 4
    for _ in range(M):
        l = int(data[idx]); r = int(data[idx+1]); idx += 2
        if ivs and l <= ivs[-1][1] + 1:
            if r > ivs[-1][1]:
                ivs[-1][1] = r
        else:
            ivs.append([l, r])

    def can(d):
        # can we cover exactly distance d through fully free squares?
        if d == 0:
            return True
        if d < A:
            return False
        k = -(-d // B)  # ceil(d/B)
        return k * A <= d

    if not ivs:
        print("Yes" if can(N - 1) else "No")
        return

    # build free stretches
    stretches = []
    prev = 1
    for l, r in ivs:
        stretches.append((prev, l - 1))
        prev = r + 1
    stretches.append((prev, N))

    win = deque()  # reachable candidate positions within sliding window of size B
    reachN = False

    for (s, e) in stretches:
        if s > e:
            continue
        c1_end = min(s + B - 1, e)
        c2_start = max(e - B + 1, s)
        if c2_start <= c1_end + 1:
            cands = range(s, e + 1)
        else:
            cands = list(range(s, c1_end + 1)) + list(range(c2_start, e + 1))
        local = []  # reachable candidates in this stretch (positions)
        for q in cands:
            r = (q == 1)
            if not r:
                # direct jumps: reachable p with q-B <= p <= q-A (may cross obstacles)
                qa = q - A
                qb = q - B
                while win and win[0] < qb:
                    win.popleft()
                for p in win:
                    if p <= qa:
                        r = True
                        break
                if not r:
                    # multi-jump within this free stretch, distance > B
                    lim = q - B
                    for p in local:
                        if p < lim:
                            d = q - p
                            k = -(-d // B)
                            if k * A <= d:
                                r = True
                                break
                        else:
                            break
            if r:
                local.append(q)
                win.append(q)
                if q == N:
                    reachN = True

    print("Yes" if reachN else "No")

