class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        # runs
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        def cost(m):
            if m == 1:
                # alternating pattern
                c1 = sum(1 for idx in range(n) if s[idx] != ('0' if idx % 2 == 0 else '1'))
                c2 = n - c1
                return min(c1, c2)
            return sum(L // (m + 1) for L in runs)

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if cost(mid) <= numOps:
                hi = mid
            else:
                lo = mid + 1
        return lo

