class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        ans = n  # delete everything
        mx = max(cnt)

        for k in range(1, mx + 1):
            # states: dict avail_from_prev -> min cost
            states = {0: 0}
            for c in cnt:
                mn = min(states.values())
                new = {}
                # Option 1: zero out this letter (cost c, all c chars can convert to next)
                new[c] = mn + c
                if c >= k:
                    # Option 2: keep at k, surplus c-k (paid, available to next letter)
                    v = mn + c - k
                    na = c - k
                    if na not in new or v < new[na]:
                        new[na] = v
                else:
                    # Option 2: raise to k using incoming conversions (free) then inserts
                    need = k - c
                    best = n * 3
                    for a, cost in states.items():
                        u = a if a < need else need
                        v = cost + need - u
                        if v < best:
                            best = v
                    if 0 not in new or best < new[0]:
                        new[0] = best
                states = new
            cand = min(states.values())
            if cand < ans:
                ans = cand
        return ans

