from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))

        def find(x):
            # path halving
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        ans = 0
        present = []
        for v in nums:
            if v > threshold:
                # cannot connect to anything: lcm with anything is >= v > threshold
                ans += 1
            else:
                present.append(v)

        # For each present value d <= threshold, union d with all multiples of d up to threshold.
        # If lcm(a,b) = m <= threshold, then m is a multiple of both a and b,
        # so a-m and b-m get unioned, connecting a and b.
        for d in present:
            rd = find(d)
            for m in range(2 * d, threshold + 1, d):
                rm = find(m)
                if rm != rd:
                    parent[rm] = rd

        roots = set()
        for v in present:
            roots.add(find(v))

        return ans + len(roots)
